 * @name scwin.tx_fn_searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "",
        ref: "dma_goWriteNextReq",
        target: "dlt_docPageList=body",
        isProcessMsg: false
    };
    return await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name scwin.tx_fn_goWrite_next
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goWrite_next = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite_next",
        method: "post",
        action: "/submission/disclosure.do?method=searchChangeDocumentDetail",
        ref: "dma_goWriteNextReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil00100.tx_fn_goWrite_next" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_197").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


